def generate_csv(output_paths):
    fieldnames = ["vasp_name", "vasp_type", "country", "risk_level", "chain", "address", "address_type", "verified", "source"]
    for p in output_paths:
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()
            for row in VASP_DATASET:
                writer.writerow(row)
        print(f"[+] Wrote {len(VASP_DATASET)} entries to {p}")

if __name__ == "__main__":
    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    paths = [
        os.path.join(base_dir, "data", "vasp_addresses.csv"),
        os.path.join(base_dir, "analyzer", "data", "vasp_addresses.csv"),
    ]
    generate_csv(paths)
